defmodule PanWeb.Live.Admin.Databrowser.SchemaDefinition do
  use PanWeb, :admin_live_view

  alias PanWeb.Admin.Naming
  require Integer

  def mount(%{"resource" => resource}, _session, socket) do
    model = Naming.model_from_resource(resource)

    tabs = [
      "Prefix",
      "Autogenerated ID",
      "Primary Key",
      "(non virtual) Fields and Field Sources",
      "Associations",
      "Redact Fields",
      "Embedded Fields",
      "Read after Write Fields",
      "Source"
    ]

    {:ok, assign(socket, resource: resource, model: model, tabs: tabs)}
  end

  def type(details) do
    details.__struct__
    |> Atom.to_string()
    |> String.split(".")
    |> List.last()
  end

  # a field's Ecto type: an atom like :string, or a composite like
  # {:array, :string} or {:parameterized, {Ecto.Enum, ...}}
  defp type_name(type) when is_atom(type), do: Atom.to_string(type)
  defp type_name(type), do: inspect(type)

  def render(assigns) do
    ~H"""
    <div class="m-2 border border-base-300 rounded">
      <h1 class="p-1 border-b border-base-300 text-center bg-base-300 font-mono">
        Schema Definition for Resource
        <span class="italic">{Naming.module_without_namespace(@model)}</span>
      </h1>

      <div x-data="{ selectedTab: 0 }">
        <ul class="flex flex-wrap border-b border-base-300 bg-base-200">
          <li :for={{title, index} <- Enum.with_index(@tabs)} class="-mb-px ml-1.5 mt-1">
            <a
              class="inline-block rounded-t px-1 border-base-300"
              x-bind:class={"{ 'disabled text-base-content bg-base-200 border-l border-t border-r':
                        selectedTab === #{index},
                        'bg-base-300 text-base-content/70 hover:text-base-content': selectedTab !== #{index} }"}
              @click.prevent={"selectedTab = #{index}"}
              to="#"
            >{title}</a>
          </li>
        </ul>
        <div class="p-4">
          <div x-show="selectedTab === 0">
            {@model.__schema__(:prefix) || "no prefix"}
          </div>

          <table :if={assigns.model.__schema__(:autogenerate_id)} x-show="selectedTab === 1">
            {{module, function, args} = assigns.model.__schema__(:autogenerate_id)
            nil}
            <thead>
              <tr>
                <th>
                  <div class="bg-base-100 mx-2">Module</div>
                </th>
                <th>
                  <div class="bg-base-100 mx-2">Function</div>
                </th>
                <th>
                  <div class="bg-base-100 mx-2">Arguments</div>
                </th>
              </tr>
            </thead>
            <tbody>
              <tr>
                <td>
                  <div class="bg-base-300">{module}</div>
                </td>
                <td>
                  <div class="bg-base-300">{function}</div>
                </td>
                <td>
                  <div class="bg-base-300">{args}</div>
                </td>
              </tr>
            </tbody>
          </table>

          <div x-show="selectedTab === 2">
            Columns:
            <span :for={key <- @model.__schema__(:primary_key)}>
              {key |> Atom.to_string()}
            </span>
          </div>

          <table x-show="selectedTab === 3">
            <thead>
              <tr>
                <th>
                  <div class="bg-base-100 mx-1">Field</div>
                </th>
                <th>
                  <div class="bg-base-100 mx-1">Alias</div>
                </th>
                <th>
                  <div class="bg-base-100 mx-1">Type</div>
                </th>
              </tr>
            </thead>
            <tbody>
              <tr :for={{field, index} <- Enum.with_index(@model.__schema__(:fields))}>
                <td>
                  <div class={[
                    "mx-1",
                    if(Integer.is_odd(index), do: "bg-base-100"),
                    if(Integer.is_even(index), do: "bg-base-300")
                  ]}>
                    {field |> Atom.to_string()}
                  </div>
                </td>
                <td>
                  <div class={[
                    "mx-1",
                    if(Integer.is_odd(index), do: "bg-base-100"),
                    if(Integer.is_even(index), do: "bg-base-300")
                  ]}>
                    {@model.__schema__(:field_source, field) |> Atom.to_string()}
                  </div>
                </td>
                <td>
                  <div class={[
                    "mx-1",
                    if(Integer.is_odd(index), do: "bg-base-100"),
                    if(Integer.is_even(index), do: "bg-base-300")
                  ]}>
                    {@model.__schema__(:type, field) |> type_name()}
                  </div>
                </td>
              </tr>
            </tbody>
          </table>

          <div x-show="selectedTab === 4">
            <div x-data="{ selectedAssociation: 0 }" class="-mt-3">
              <ul class="flex flex-wrap border-b border-base-300 bg-base-200">
                <li
                  :for={
                    {association, assoc_index} <- Enum.with_index(@model.__schema__(:associations))
                  }
                  class="-mb-px ml-1.5 mt-1"
                >
                  <a
                    class="inline-block rounded-t px-1 border-base-300"
                    x-bind:class={"{ 'disabled text-base-content bg-base-200 border-l border-t border-r':
                              selectedAssociation === #{assoc_index},
                              'bg-base-300 text-base-content/70 hover:text-base-content': selectedAssociation !== #{assoc_index} }"}
                    @click.prevent={"selectedAssociation = #{assoc_index}"}
                    to="#"
                  >{association |> Atom.to_string()}</a>
                </li>
              </ul>
              <div
                :for={
                  {details, assoc_index} <-
                    @model.__schema__(:associations)
                    |> Enum.map(&@model.__schema__(:association, &1))
                    |> Enum.with_index()
                }
                x-show={"selectedAssociation === #{assoc_index}"}
                class="p-4 border-l border-r border-b border-base-300"
              >
                <table cellspacing="4px" class="border-separate">
                  <tr>
                    <td class="bg-base-100">
                      <div class="font-mono">Type</div>
                    </td>
                    <td class="bg-base-100">
                      <div>{type(details)}</div>
                    </td>
                  </tr>
                  <tr>
                    <td class="bg-base-100">
                      <div class="font-mono">Cardinality</div>
                    </td>
                    <td class="bg-base-100">
                      <div>{details.cardinality |> Atom.to_string()}</div>
                    </td>
                  </tr>
                  <tr :if={Map.has_key?(details, :defaults)}>
                    <td class="bg-base-100">
                      <div class="font-mono">Defaults</div>
                    </td>
                    <td class="bg-base-100">
                      <div
                        :for={default <- details.defaults}
                        class="mx-1 flex space-x-2 justify-start"
                      >
                        {inspect(default)}
                      </div>
                    </td>
                  </tr>
                  <tr>
                    <td class="bg-base-100">
                      <div class="font-mono">Field</div>
                    </td>
                    <td class="bg-base-100">
                      <div>{details.field |> Atom.to_string()}</div>
                    </td>
                  </tr>
                  <tr :if={Map.has_key?(details, :join_defaults)}>
                    <td class="bg-base-100">
                      <div class="font-mono">Join Defaults</div>
                    </td>
                    <td class="bg-base-100">
                      <div
                        :for={default <- details.join_defaults}
                        class="mx-1 flex space-x-2 justify-start"
                      >
                        {inspect(default)}
                      </div>
                    </td>
                  </tr>
                  <tr :if={Map.has_key?(details, :join_keys)}>
                    <td class="bg-base-100">
                      <div class="font-mono">Join Keys</div>
                    </td>
                    <td class="bg-base-100">
                      <div class="mx-1 flex space-x-4">
                        <div :for={{key, value} <- details.join_keys}>
                          {key |> Atom.to_string()}: {value |> Atom.to_string()}
                        </div>
                      </div>
                    </td>
                  </tr>
                  <tr :if={Map.has_key?(details, :join_through)}>
                    <td class="bg-base-100">
                      <div class="font-mono">Join Through</div>
                    </td>
                    <td class="bg-base-100">
                      <div>{details.join_through}</div>
                    </td>
                  </tr>
                  <tr :if={Map.has_key?(details, :join_where)}>
                    <td class="bg-base-100">
                      <div class="font-mono">Join Where</div>
                    </td>
                    <td class="bg-base-100">
                      <div
                        :for={{key, value} <- details.join_where}
                        class="mx-1 flex space-x-2 justify-start"
                      >
                        {key |> Atom.to_string()}: {value |> Atom.to_string()}
                      </div>
                    </td>
                  </tr>
                  <tr :if={Map.has_key?(details, :on_cast)}>
                    <td class="bg-base-100">
                      <div class="font-mono">On Cast</div>
                    </td>
                    <td class="bg-base-100">
                      <div>{details.on_cast |> Atom.to_string()}</div>
                    </td>
                  </tr>
                  <tr :if={Map.has_key?(details, :on_replace)}>
                    <td class="bg-base-100">
                      <div class="font-mono">On Replace</div>
                    </td>
                    <td class="bg-base-100">
                      <div>{details.on_replace |> Atom.to_string()}</div>
                    </td>
                  </tr>
                  <tr :if={Map.has_key?(details, :on_delete)}>
                    <td class="bg-base-100">
                      <div class="font-mono">On Delete</div>
                    </td>
                    <td class="bg-base-100">
                      <div>{details.on_delete |> Atom.to_string()}</div>
                    </td>
                  </tr>
                  <tr :if={Map.has_key?(details, :ordered)}>
                    <td class="bg-base-100">
                      <div class="font-mono">Ordered</div>
                    </td>
                    <td class="bg-base-100">
                      <div>{details.ordered |> Atom.to_string()}</div>
                    </td>
                  </tr>
                  <tr :if={Map.has_key?(details, :owner)}>
                    <td class="bg-base-100">
                      <div class="font-mono">Owner</div>
                    </td>
                    <td class="bg-base-100">
                      <div>{details.owner |> Atom.to_string()}</div>
                    </td>
                  </tr>
                  <tr :if={Map.has_key?(details, :owner_key)}>
                    <td class="bg-base-100">
                      <div class="font-mono">Owner Key</div>
                    </td>
                    <td class="bg-base-100">
                      <div>{details.owner_key |> Atom.to_string()}</div>
                    </td>
                  </tr>
                  <tr :if={Map.has_key?(details, :queryable)}>
                    <td class="bg-base-100">
                      <div class="font-mono">Queryable</div>
                    </td>
                    <td class="bg-base-100">
                      <div>{details.queryable |> Atom.to_string()}</div>
                    </td>
                  </tr>
                  <tr :if={Map.has_key?(details, :related)}>
                    <td class="bg-base-100">
                      <div class="font-mono">Related</div>
                    </td>
                    <td class="bg-base-100">
                      <div>{details.related |> Atom.to_string()}</div>
                    </td>
                  </tr>
                  <tr :if={Map.has_key?(details, :related_key)}>
                    <td class="bg-base-100">
                      <div class="font-mono">Related Key</div>
                    </td>
                    <td class="bg-base-100">
                      <div>{details.related_key |> Atom.to_string()}</div>
                    </td>
                  </tr>
                  <tr :if={Map.has_key?(details, :relationship)}>
                    <td class="bg-base-100">
                      <div class="font-mono">Relationship</div>
                    </td>
                    <td class="bg-base-100">
                      <div>{details.relationship |> Atom.to_string()}</div>
                    </td>
                  </tr>
                  <tr :if={Map.has_key?(details, :unique)}>
                    <td class="bg-base-100">
                      <div class="font-mono">Unique</div>
                    </td>
                    <td class="bg-base-100">
                      <div>{details.unique |> Atom.to_string()}</div>
                    </td>
                  </tr>
                  <tr :if={Map.has_key?(details, :where)}>
                    <td class="bg-base-100">
                      <div class="font-mono">Where</div>
                    </td>
                    <td>
                      <div :for={where <- details.where} class="flex space-x-2 justify-start">
                        {inspect(where)}
                      </div>
                    </td>
                  </tr>
                </table>
              </div>
            </div>
          </div>

          <div x-show="selectedTab === 5">
            <div :for={field <- @model.__schema__(:redact_fields)}>
              {field |> Atom.to_string()}
            </div>
            <div :if={@model.__schema__(:redact_fields) == []}>none</div>
          </div>

          <div x-show="selectedTab === 6">
            <div :for={field <- @model.__schema__(:embeds)}>
              {field |> Atom.to_string()}
            </div>
            <div :if={@model.__schema__(:embeds) == []}>none</div>
          </div>

          <div x-show="selectedTab === 7">
            <div :for={field <- @model.__schema__(:read_after_writes)}>
              {field |> Atom.to_string()}
            </div>
            <div :if={@model.__schema__(:read_after_writes) == []}>none</div>
          </div>

          <div x-show="selectedTab === 8">
            {@model.__schema__(:source)}
          </div>
        </div>
      </div>
    </div>
    """
  end
end
